const STYLES: &[&str] = &[
    "plain",
    "pretty",
    "width",
    "left",
    "right",
    "center",
    "precision",
    "plus",
    "zero_pad",
    "lower_hex",
    "upper_hex",
    "pretty_lower_hex",
    "pretty_upper_hex",
];

fn write_style(writer: &mut impl Write, style: &str, value: &impl Debug) -> fmt::Result {
    match style {
        "plain" => write!(writer, "{value:?}"),
        "pretty" => write!(writer, "{value:#?}"),
        "width" => write!(writer, "{value:24?}"),
        "left" => write!(writer, "{value:<24?}"),
        "right" => write!(writer, "{value:>24?}"),
        "center" => write!(writer, "{value:^24?}"),
        "precision" => write!(writer, "{value:.3?}"),
        "plus" => write!(writer, "{value:+?}"),
        "zero_pad" => write!(writer, "{value:024?}"),
        "lower_hex" => write!(writer, "{value:x?}"),
        "upper_hex" => write!(writer, "{value:X?}"),
        "pretty_lower_hex" => write!(writer, "{value:#x?}"),
        "pretty_upper_hex" => write!(writer, "{value:#X?}"),
        other => panic!("unknown fixed oracle style: {other}"),
    }
}

struct PrefixSink {
    limit: usize,
    bytes: Vec<u8>,
}
impl Write for PrefixSink {
    fn write_str(&mut self, value: &str) -> fmt::Result {
        let remaining = self.limit - self.bytes.len();
        let taken = value.len().min(remaining);
        self.bytes.extend_from_slice(&value.as_bytes()[..taken]);
        if taken == value.len() {
            Ok(())
        } else {
            Err(fmt::Error)
        }
    }
}

fn fixtures() -> Vec<(&'static str, V)> {
    let pattern = i256::from_le_bytes([
        0xff, 0x01, 0x80, 0x0f, 0x42, 0x99, 0x7f, 0x13, 0x65, 0x90, 0x34, 0xee, 0x10, 0x00, 0x98,
        0xab, 0x57, 0x56, 0x08, 0x12, 0x00, 0xef, 0xcd, 0xaa, 0x99, 0x88, 0x00, 0x00, 0x00, 0x20,
        0x10, 0x07,
    ]);
    let nested = vec![
        None,
        Some(V::Decimal256(i256::MIN)),
        Some(V::Struct(vec![Some(V::Utf8("é中\0\n\"\\".into())), None])),
        Some(V::Map(vec![
            (None, Some(V::Decimal256(pattern))),
            (
                Some(V::Bool(false)),
                Some(V::List(vec![Some(V::Binary(vec![0, 15, 128, 255]))])),
            ),
        ])),
    ];
    vec![
        ("bool_false", V::Bool(false)),
        ("bool_true", V::Bool(true)),
        ("int_min", V::Int64(i64::MIN)),
        ("int_max", V::Int64(i64::MAX)),
        ("float_negative_zero", V::Float64(-0.0)),
        (
            "float_nan",
            V::Float64(f64::from_bits(0x7ff8_0000_0000_0001)),
        ),
        ("float_infinity", V::Float64(f64::INFINITY)),
        ("float_negative_infinity", V::Float64(f64::NEG_INFINITY)),
        ("float_smallest", V::Float64(f64::from_bits(1))),
        ("float_max", V::Float64(f64::MAX)),
        ("float_ordinary", V::Float64(-12.3456789)),
        (
            "utf8_escaped",
            V::Utf8("\0\u{1}\r\n\t\"\\é中\u{200d}".into()),
        ),
        ("date_min", V::Date32(i32::MIN)),
        ("timestamp_min", V::Timestamp(i64::MIN)),
        ("decimal128_min", V::Decimal128(i128::MIN)),
        ("decimal128_max", V::Decimal128(i128::MAX)),
        ("decimal256_min", V::Decimal256(i256::MIN)),
        ("decimal256_max", V::Decimal256(i256::MAX)),
        ("decimal256_zero", V::Decimal256(i256::ZERO)),
        ("decimal256_negative", V::Decimal256(i256::MINUS_ONE)),
        ("decimal256_all_limbs", V::Decimal256(pattern)),
        ("binary", V::Binary(vec![0, 9, 15, 16, 127, 128, 255])),
        ("empty_struct", V::Struct(vec![])),
        ("nested_struct", V::Struct(nested.clone())),
        ("empty_map", V::Map(vec![])),
        (
            "nested_map",
            V::Map(vec![
                (None, None),
                (
                    Some(V::List(nested.clone())),
                    Some(V::Decimal256(i256::MAX)),
                ),
            ]),
        ),
        ("empty_list", V::List(vec![])),
        ("nested_list", V::List(nested)),
    ]
}

fn append_records(
    records: &mut Vec<serde_json::Value>,
    name: &str,
    root: &str,
    value: &impl Debug,
) {
    for &style in STYLES {
        let mut complete = String::new();
        write_style(&mut complete, style, value).unwrap();
        let mut limits = vec![
            0,
            1,
            2,
            4,
            7,
            complete.len() / 2,
            complete.len().saturating_sub(1),
            complete.len(),
            complete.len() + 1,
        ];
        limits.sort_unstable();
        limits.dedup();
        let failures: Vec<_> = limits
            .into_iter()
            .map(|limit| {
                let mut writer = PrefixSink {
                    limit,
                    bytes: Vec::new(),
                };
                let failed = write_style(&mut writer, style, value).is_err();
                assert_eq!(
                    writer.bytes,
                    complete.as_bytes()[..complete.len().min(limit)]
                );
                assert_eq!(failed, limit < complete.len());
                serde_json::json!({ "limit": limit, "failed": failed })
            })
            .collect();
        records.push(serde_json::json!({ "case": name, "root": root, "style": style, "text": complete, "failures": failures }));
    }
}

#[test]
fn c16_p1_scalar_debug_frozen_legacy_bytes_flags_and_public_writer_errors() {
    let mut records = Vec::new();
    for (name, scalar) in fixtures() {
        append_records(&mut records, name, "enum", &scalar);
        match &scalar {
            V::Struct(values) | V::List(values) => {
                append_records(&mut records, name, "json_object_inner_vec", values)
            }
            V::Map(values) => append_records(&mut records, name, "json_object_inner_pairs", values),
            _ => {}
        }
    }
    let expected: Vec<serde_json::Value> = serde_json::from_str(LEGACY_ORACLE_JSON).unwrap();
    assert_eq!(
        records, expected,
        "public Debug or original inner Vec formatting changed"
    );
}
